#if canImport(Compression)
import Foundation

// MARK: - Monthly check: build the map and station list from MTA's zip
//
// The first time the subway (or bus) is used after the 1st of each month, the app downloads MTA's static GTFS (see App/Services/SubwayMapStore.swift),
// and here builds the map, station catalog, express data and bus stop catalog, in the same format as the bundled ones (generated by the scripts in tools/).
// The huge stop_times.txt is read while unzipping, never held in memory whole.

public enum StaticRefresh {

    /// Result of one subway check
    public struct Subway {
        public var map: SubwayMap
        /// subway_stations.json
        public var stations: Data
        /// express_stops.json
        public var express: Data
        /// Rows of stop_times.txt and stations skipped as unreadable (at most one in a hundred, see SubwayStaticBuilder.tooMany)
        public var skipped = 0
    }

    /// gtfs_subway.zip → subway map, station catalog and express data.
    /// - Parameter catalog: The station catalog in use: station complexes, boroughs and signage direction names come from it (GTFS lacks them).
    public static func subway(zip: Data, labelsFrom catalog: StationCatalog?) throws -> Subway {
        let map: SubwayMap
        let builder: SubwayStaticBuilder
        do {
            let files = try ZipReader.read(zip, names: ["routes.txt", "trips.txt", "shapes.txt", "stops.txt", "feed_info.txt"])
            map = try SubwayMapBuilder.build(files: files)
            builder = try SubwayStaticBuilder(stops: try file(files, "stops.txt"), trips: try file(files, "trips.txt"),
                                              feedInfo: files["feed_info.txt"], labelsFrom: catalog)
        }
        try ZipReader.forEachRow(zip, name: "stop_times.txt") { builder.addStopTimeRow($0) }
        let stations = try builder.stationsJSON(), express = try builder.expressJSON()
        return Subway(map: map, stations: stations, express: express, skipped: builder.badSequences + builder.badStations)
    }

    /// Bus: the 6 feeds go to add(zip:) in BusMap.sourceURLs order (route order and "first one wins on a tie" depend on it),
    /// download the next only after one is processed, then finish().
    public final class Bus {
        private var map = BusMapBuilder()
        private let stops = BusStaticBuilder()

        public init() {}

        public func add(zip: Data) throws {
            do {
                var files = try ZipReader.read(zip, names: ["routes.txt", "trips.txt", "shapes.txt", "stops.txt", "feed_info.txt"])
                try map.add(files: files)
                files["shapes.txt"] = nil   // shape data is huge; release it before reading stop_times.txt
                try stops.beginFeed(routes: try StaticRefresh.file(files, "routes.txt"),
                                    stops: try StaticRefresh.file(files, "stops.txt"),
                                    trips: try StaticRefresh.file(files, "trips.txt"),
                                    feedInfo: files["feed_info.txt"])
            }
            let builder = stops
            try ZipReader.forEachRow(zip, name: "stop_times.txt") { builder.addStopTimeRow($0) }
            builder.endFeed()
        }

        /// Bus map and bus_stops.json
        public func finish() throws -> (map: SubwayMap, stops: Data) {
            (try map.build(), try stops.stopsJSON())
        }
    }

    /// Roosevelt Island Tram GTFS (compiled by Trillium) → daily operating hours (see RooseveltIslandTram.hours).
    public static func tramHours(zip: Data) throws -> RooseveltIslandTram.Hours {
        let files = try ZipReader.read(zip, names: ["routes.txt", "trips.txt", "stop_times.txt", "calendar.txt", "feed_info.txt"])
        var version = ""
        if let info = files["feed_info.txt"] {
            try TimetableBuilder.forEachRow(info) { col in
                if version.isEmpty { version = col("feed_version") ?? col("feed_start_date") ?? "" }
            }
        }
        return try RooseveltIslandTram.hours(routes: try file(files, "routes.txt"), trips: try file(files, "trips.txt"),
                                             stopTimes: try file(files, "stop_times.txt"),
                                             calendar: try file(files, "calendar.txt"), version: version)
    }

    static func file(_ files: [String: Data], _ name: String) throws -> Data {
        guard let data = files[name] else { throw TimetableError.missingFile(name) }
        return data
    }
}
#endif
